const newItems = [];

for (const item of $input.all()) {
  const archivos = item.json.lista_archivos;
  if (archivos && Array.isArray(archivos)) {
    for (const archivo of archivos) {
      if (archivo.google_drive_file_id) {
        newItems.push({
          json: {
            id: archivo.google_drive_file_id
          }
        });
      }
    }
  }
}

return newItems;

const body = $('sesiones/upsert1').first().json.body;
const quote_id = parseInt(body.quote_id, 10);
const appointment_id = body.appointment_id ? parseInt(body.appointment_id, 10) : null;

let query;
if (appointment_id) {
  query = `UPDATE order_items oi
  SET status = 'completed', completed_date = NOW()
  FROM orders o, quote_items qi, appointment_service_catalog asc_
  WHERE oi.order_id = o.id
    AND o.quote_id = ${quote_id}
    AND qi.id = oi.quote_item_id
    AND asc_.service_id = qi.service_id
    AND asc_.appointment_id = ${appointment_id}
    AND oi.status = 'scheduled'
  RETURNING oi.id, oi.order_id`;
} else {
  query = `UPDATE order_items oi
  SET status = 'completed', completed_date = NOW()
  FROM orders o
  WHERE oi.order_id = o.id
    AND o.quote_id = ${quote_id}
    AND oi.status = 'scheduled'
  RETURNING oi.id, oi.order_id`;
}

return [{ json: { query, quote_id, appointment_id } }];

