// Recopilar información final y generar respuesta para n8n v1.109.3
const allItems = $input.all();
const totalFiles = allItems.length;

// Verificar archivos exitosamente procesados
const successfulUploads = allItems.filter(item => 
  item.json && (item.json.success)
).length;

const failedUploads = totalFiles - successfulUploads;

// Generar resumen de archivos procesados
const filesInfo = allItems.map((item, index) => {
  const json = item.json.data || {};
  return {
    index: index,
    filename: json.file_name || 'unknown',
    drive_id: json.drive_file_id || json.id || null,
    public_url: json.web_view_link || null,
    download_url: json.web_view_link || null,
    mime_type: json.mime_type || null,
    file_size: null,
    status: (json.drive_file_id || json.id) ? 'success' : 'failed',
    original_key: null
  };
});

const summary = {
  status: failedUploads === 0 ? 'completed' : 'partial',
  total_files_received: totalFiles,
  successful_uploads: successfulUploads,
  failed_uploads: failedUploads,
  files: filesInfo,
  processing_completed_at: new Date().toISOString()
};

return [{ json: summary }];

const item = $('POST /upsert_odontogram').first();
const binaryData = item.binary;
const newItems = [];

// Detectar dinámicamente el ID de la sesión devuelto por la base de datos
const sessionId = $input.first() ? $input.first().json.id : null;

for (const key in binaryData) {
    if (binaryData.hasOwnProperty(key) && binaryData[key]) {
        const fileObject = binaryData[key];

        const newItem = {
            json: {
                sessionId: sessionId,
                binaryPropertyName: key,
                fileName: fileObject.fileName,
                mimeType: fileObject.mimeType
            },
            binary: {
                data: fileObject
            }
        };

        newItems.push(newItem);
    }
}

return newItems;

for (const item of $input.all()) {
  let rawOutput = item.json.output;

  if (rawOutput && typeof rawOutput === 'string') {
    const regexMatch = rawOutput.match(/```json\s*([\s\S]*?)\s*```/);
    const jsonString = regexMatch ? regexMatch[1] : rawOutput;

    try {
      const parsedJson = JSON.parse(jsonString.trim());
      item.json = parsedJson;
    } catch (error) {
      item.json.error = "No se pudo parsear el output del LLM como JSON.";
      item.json.raw_output = rawOutput;
    }
  }
}

return $input.all();
